Get-ChildItem -Path 'C:\Users\rafal\AppData\Local\Temp\rename-bench-no-tool-xqPOUc\workspace\src\app\features' -Recurse -Include '*.ts', '*.html' | ForEach-Object {
    if ($_ | Select-String -Pattern 'disableTooltip' -Quiet) {
        $files += $_.FullName
    }
}

Write-Host "Found $($files.Count) files to process"
$files | ForEach-Object { Write-Host $_ }
